import json,re,glob
pat=re.compile(r'生成の方式|適用先と順序|適用先')
seen=set()
for p in ['8fcf0e26-15e1-4158-898d-a1dfc4b35394.jsonl','94fd152b-e07e-4143-9a69-ed8ec9abfe57.jsonl']:
    try: f=open(p,encoding='utf-8')
    except Exception as e: print(e); continue
    for i,line in enumerate(f):
        if not pat.search(line): continue
        try: o=json.loads(line)
        except Exception: continue
        m=o.get('message') or {}
        c=m.get('content')
        if not isinstance(c,list): continue
        for b in c:
            if b.get('type')=='text' and pat.search(b['text']):
                for mm in pat.finditer(b['text']):
                    s=max(0,mm.start()-250); t=b['text'][s:mm.end()+450]
                    k=t[:80]
                    if k in seen: continue
                    seen.add(k)
                    print('---',p[:8],i,m.get('role')); print(t)
                    if len(seen)>7: raise SystemExit
EOF

